import { Cart, Category, ContactPointAddress, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Checkout step in which the shopper enters a shipping address.
*/
export type CheckoutShippingAddress = {
    events: Array<Cart | ContactPointAddress | Identity | PartyIdentification | ErrorEvent>;
}

export class CheckoutShippingAddressBuilder {

    private checkoutShippingAddress: CheckoutShippingAddress = {
        events: []
    }

    private cart!: Cart;
    private contactPointAddress!: ContactPointAddress;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : CheckoutShippingAddressBuilder {
        this.cart = cart;
        return this;
    }
    public withContactPointAddress(contactPointAddress: ContactPointAddress) : CheckoutShippingAddressBuilder {
        this.contactPointAddress = contactPointAddress;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : CheckoutShippingAddressBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : CheckoutShippingAddressBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : CheckoutShippingAddressBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : CheckoutShippingAddress {
        if(this.cart) {
            this.checkoutShippingAddress.events.push(this.cart);
        }
        if(this.contactPointAddress) {
            this.checkoutShippingAddress.events.push(this.contactPointAddress);
        }
        if(this.errorEvent) {
            this.checkoutShippingAddress.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.checkoutShippingAddress.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.checkoutShippingAddress.events.push(this.partyIdentification);
        }

        return this.checkoutShippingAddress;
    }
}
